using System;using System.IO;using System.Linq;using System.Reflection;using System.Windows.Forms;using System.Xml;using System.Text;using BeamScheduleFormatter;
class PowSourceFilesUiTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}static T Get<T>(object o,string name){return (T)o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static BeamRow Row(){var r=new BeamRow{Mark="GB-1",Leg="2L",Diameter="O10",RevisedSpacing="1 - 50mm, REST AT 150mm TO FREE END"};for(int n=0;n<14;n++)r.Cells[n].Add("-");r.Cells[0][0]="300";r.Cells[1][0]="500";for(int n=2;n<8;n++)r.Cells[n][0]="2-O16";return r;}
 [STAThread]static void Main(){Application.EnableVisualStyles();AccessCodes.Granted=true;string previous=ProjectInfoStore.DirectoryPath,dir=Path.Combine(Path.GetTempPath(),"DTCE-source-ui-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);ProjectInfoStore.DirectoryPath=dir;try{string path=Path.Combine(dir,"Original.dxf"),image=Path.Combine(dir,"Reference.png"),pow=Path.Combine(dir,"Whole.pow.xml");var a=new Analysis();a.Source.Add(Row());string raw=ManualBeamSchedule.Serialize(a);byte[] bytes=Encoding.UTF8.GetPreamble().Concat(Encoding.UTF8.GetBytes(raw)).ToArray();File.WriteAllBytes(path,bytes);File.WriteAllBytes(image,new byte[]{137,80,78,71,0,255,3,7});string xml;
 using(var f=new ProgramOfWorksForm()){var beam=Get<EstimatorForm>(f,"beam");beam.LoadCatalog(raw,"Original.dxf");beam.sourceAttachments.CaptureFile(path,"Beam DXF");beam.AddEntry("Valid source","GB-1","2","1");Get<PowSourceFiles>(f,"projectSourceFiles").CaptureFile(image,"Project attachment");f.SaveTo(pow);xml=File.ReadAllText(pow);var d=new XmlDocument();d.LoadXml(xml);Check(PowSourceFiles.Read(d.DocumentElement).Files.Count==2,"Whole POW includes original drawing and reference image");var b=new XmlDocument();b.LoadXml(d.DocumentElement["Beam"].InnerText);((XmlElement)b.SelectSingleNode("//Entry")).SetAttribute("schedule","Missing old floor label");var pending=(XmlElement)b.SelectSingleNode("//Entry").CloneNode(true);pending.SetAttribute("mark","FUTURE-9");pending.SetAttribute("quantity","3");b.DocumentElement.AppendChild(pending);d.DocumentElement["Beam"].InnerText=b.OuterXml;xml=d.OuterXml;}
 File.Delete(path);File.Delete(image);using(var reopened=new ProgramOfWorksForm()){reopened.OpenProjectXml(xml);var g=Get<EstimatorForm>(reopened,"beam").WorksInputGrid;Check(Convert.ToString(g.Rows[0].Cells[1].Value)=="GB-1","Stale floor label repaired without original DXF on disk");Check(Convert.ToString(g.Rows[1].Cells[1].Value)=="FUTURE-9"&&Convert.ToString(g.Rows[1].Cells[5].Value)=="3","Missing beam mark preserved as pending instead of aborting Open");Check(reopened.WorksValidationIssues().Count>0,"Unresolved mark remains visible in input review");string next=Path.Combine(dir,"Recovered.pow.xml");reopened.SaveTo(next);var d=new XmlDocument();d.Load(next);var attachments=PowSourceFiles.Read(d.DocumentElement);Check(attachments.Files.Count==2,"Re-saving does not duplicate recovered DXF text alongside original");Check(attachments.Files.Single(f=>f.Name=="Original.dxf").Bytes().SequenceEqual(bytes),"Original BOM and bytes survive full native POW save/open/save");}
 Console.WriteLine("PASS: "+checks+" native self-contained POW source and missing-reference recovery checks");}finally{ProjectInfoStore.DirectoryPath=previous;Directory.Delete(dir,true);}}
}
